<?php require 'conexion.php';$d=body();$nombre=trim($d['nombre']??'');$celular=trim($d['celular']??'');$correo=strtolower(trim($d['correo']??''));$pass=$d['contrasena']??'';if(!$nombre||!$celular||!filter_var($correo,FILTER_VALIDATE_EMAIL)||strlen($pass)<4)out(['ok'=>false,'mensaje'=>'Completa correctamente todos los campos.'],422);try{$s=$pdo->prepare('INSERT INTO usuarios(nombre,celular,correo,contrasena) VALUES(?,?,?,?)');$s->execute([$nombre,$celular,$correo,password_hash($pass,PASSWORD_DEFAULT)]);$id=$pdo->lastInsertId();out(['ok'=>true,'usuario'=>['id'=>(int)$id,'nombre'=>$nombre,'celular'=>$celular,'correo'=>$correo]]);}catch(PDOException $e){out(['ok'=>false,'mensaje'=>'Ese correo ya está registrado.'],409);}
